makeMtLab(document.getElementById("lab-l24"),{id:"l24",scenarios:[{"label": "Ví dụ: Tạo một sự kiện", "note": "Dataclass với Enum.", "steps": [{"t": "StateEvent(...)", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">e = StateEvent(\"L1-M1\", State.DOWN, t0, t1, 12)<\/span><\/div>"}, {"t": "e.seconds()", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">2400.0<\/span><\/div>", "ask": {"q": "Sự kiện 09:00–09:40 dài bao nhiêu giây?", "o": ["40", "2 400", "240"], "a": 1}}]}, {"label": "Ví dụ: Cộng định mức bằng Decimal", "note": "Decimal tạo từ chuỗi.", "steps": [{"t": "Decimal('0.500') × 10 200", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">Decimal('5100.000')<\/span><\/div>"}, {"t": "Cộng 10 200 lần 0.5 bằng float", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">5100.0<\/span><\/div>", "say": "<p>0,5 biểu diễn chính xác ở cơ số 2 nên lần này không lệch; 0,1 thì có.<\/p>"}]}, {"label": "Ví dụ: Enum chặn trạng thái sai", "note": "Chỉ bốn giá trị.", "steps": [{"t": "State('RUNING')", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">ValueError: 'RUNING' is not a valid State<\/span><\/div>"}, {"t": "Lỗi chính tả bị bắt ngay", "html": "<p class=\"mt-calc\">Thay vì lưu chuỗi sai vào CSDL<\/p>"}]}, {"label": "Lỗi: So sánh số thực bằng ==", "note": "0,1 × 3 khác 0,3.", "steps": [{"t": "if kg == 0.3:", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">False<\/span><\/div>"}, {"t": "Sửa", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">if abs(kg - 0.3) &lt; 1e-9:  # hoặc dùng Decimal<\/span><\/div>"}]}, {"label": "Bẫy: Decimal tạo từ số thực", "note": "Decimal(0.1) mang theo sai số.", "steps": [{"t": "Decimal(0.1)", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">Decimal('0.1000000000000000055511151231257827021181583404541015625')<\/span><\/div>"}, {"t": "Sửa", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">Decimal('0.1')<\/span><\/div>", "say": "<p>Luôn tạo Decimal từ chuỗi.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l24"),"l24",[{"kind": "num", "t": "Kiểu và giá trị", "d": "<p>Trả lời bằng một số.<\/p>", "items": [{"q": "Sự kiện 06:00–09:00 dài bao nhiêu giây?", "a": 10800, "unit": "s"}, {"q": "Lưu 0,500 kg dưới dạng số nguyên gam là bao nhiêu?", "a": 500, "unit": "g"}, {"q": "Enum State trong bài có bao nhiêu giá trị?", "a": 4}], "hints": ["3 giờ × 3 600 s.", "1 kg = 1 000 g."], "why": "10 800 s; 500 g; 4 giá trị."}, {"kind": "pick", "t": "Chọn kiểu", "d": "<p>Kiểu Python phù hợp nhất.<\/p>", "cats": ["int", "Decimal", "datetime", "Enum"], "items": [{"q": "Số hộp đạt", "a": 0}, {"q": "Định mức hạt 0,500 kg cho tính tiêu hao", "a": 1}, {"q": "Thời điểm bắt đầu dừng", "a": 2}, {"q": "Trạng thái máy", "a": 3}, {"q": "Mã lỗi PLC D101", "a": 0}], "hints": ["Đếm được: int.", "Cần chính xác thập phân: Decimal; tập giá trị cố định: Enum."], "why": "Số đếm, mã lỗi: int; định mức: Decimal; thời điểm: datetime; trạng thái: Enum."}, {"kind": "order", "t": "Viết một dataclass", "d": "<p>Sắp xếp.<\/p>", "items": ["from dataclasses import dataclass", "@dataclass(frozen=True)", "class StateEvent:", "    machine_id: str", "    def seconds(self) -> float:"], "hints": ["Import trước.", "Trình trang trí đứng ngay trên class."], "why": "import → @dataclass → class → trường → phương thức."}]);
mesSim(document.getElementById("sim-l24"),Object.assign({id:"l24"},{kind:"term",title:"Python tương tác: kiểu dữ liệu",sub:"Gõ biểu thức sau dấu >>>. Phép tính số thực chạy thật (cùng chuẩn IEEE 754 với Python).",prompt:">>> ",
 banner:"Python 3.13.0 (tags/v3.13.0) on win32\nType \"help\" for more information.",vars:{dec:false,ev:false},
 hints:["0.1 * 3","0.1 * 3 == 0.3","from decimal import Decimal","Decimal(\"0.1\") * 3","Decimal(0.1)","10500 // 1800","e = StateEvent(\"L1-M1\", State.DOWN, t)","e.state = State.RUNNING","State(\"STOPPED\")"],
 cmds:[{re:/^from decimal import Decimal$/,out:"",fx:(m,S)=>{S.dec=true}},
  {re:/^Decimal\("([\d.]+)"\)\s*\*\s*(\d+)$/,out:(m,S)=>S.dec?"Decimal('"+(m[1]*m[2]).toFixed((m[1].split(".")[1]||"").length)+"')":{err:"NameError: name 'Decimal' is not defined"}},
  {re:/^Decimal\(0\.1\)$/,out:(m,S)=>S.dec?"Decimal('0.1000000000000000055511151231257827021181583404541015625')":{err:"NameError: name 'Decimal' is not defined"}},
  {re:/^e = StateEvent\(.*\)$/,out:"",fx:(m,S)=>{S.ev=true}},{re:/^e\.state = .*$/,out:(m,S)=>S.ev?{err:"dataclasses.FrozenInstanceError: cannot assign to field 'state'"}:{err:"NameError: name 'e' is not defined"}},
  {re:/^State\("(\w+)"\)$/,out:m=>["RUNNING","IDLE","DOWN","NO_DATA"].includes(m[1])?"<State."+m[1]+": '"+m[1]+"'>":{err:"ValueError: '"+m[1]+"' is not a valid State"}},
  {re:/^[\d\s.+\-*/()=<>!]+$/,out:m=>{let x=m[0].replace(/\/\//g,"__FD__");try{if(/__FD__/.test(x)){const [a,b]=x.split("__FD__").map(Number);return String(Math.floor(a/b))}
     const r=Function("return ("+x.replace(/==/g,"===")+")")();return typeof r==="boolean"?(r?"True":"False"):Number.isInteger(r)&&!/\./.test(x)?String(r):(Number.isInteger(r)?r.toFixed(1):String(r))}catch(e){return{err:"SyntaxError: invalid syntax"}}}}],
 unknown:x=>"NameError: name '"+x.split(/[\s(.=]/)[0]+"' is not defined",
 tasks:[{t:"Gõ <code>0.1 * 3</code> rồi <code>0.1 * 3 == 0.3</code>.",ok:"0.30000000000000004 và False: số thực lưu ở cơ số 2.",check:s=>s.ran(/^0\.1 \* 3$/)&&s.ran(/^0\.1 \* 3 == 0\.3$/)},
  {t:"Dùng Decimal để tính đúng 0,1 × 3.",hint:"from decimal import Decimal rồi Decimal(\"0.1\") * 3 (truyền chuỗi, không truyền số thực).",ok:"Decimal('0.3'): định mức, tiền dùng Decimal tạo từ chuỗi.",check:(s,c)=>c.has("cmd",e=>/^Decimal\("0\.1"\)/.test(e.line)&&e.ok)},
  {t:"Tạo một StateEvent rồi thử sửa trạng thái của nó.",ok:"frozen=True: sự kiện đã ghi thì không sửa được; muốn đổi thì tạo sự kiện mới.",check:(s,c)=>c.has("cmd",e=>/^e\.state/.test(e.line)&&/Frozen/.test(e.out))},
  {t:"Thử tạo trạng thái không hợp lệ <code>State(\"STOPPED\")</code>.",ok:"Enum chặn giá trị lạ ngay khi tạo, thay vì để chuỗi sai lọt vào CSDL.",check:(s,c)=>c.has("cmd",e=>/STOPPED/.test(e.line))}]}));

